CREATE TABLE carts(id UUID PRIMARY KEY,user_id UUID UNIQUE NOT NULL,updated_at TIMESTAMPTZ NOT NULL);CREATE TABLE cart_items(id UUID PRIMARY KEY,cart_id UUID NOT NULL REFERENCES carts(id) ON DELETE CASCADE,product_id UUID NOT NULL,product_name VARCHAR(200) NOT NULL,unit_price NUMERIC(12,2) NOT NULL,quantity INT NOT NULL CHECK(quantity>0),UNIQUE(cart_id,product_id));CREATE INDEX idx_cart_user ON carts(user_id);
